#define BATTLEFIELD_SAMPLE_LIBRARY
#include "battlefield_world_sample.cpp"
#include "engine/world_structure_runtime.h"
#include "engine/world_playtest_walk.h"
#include <cassert>
int main(){assert(initialize_world()==0);std::ifstream in("world.studio");std::string line;world_structure::Definition bridge;while(std::getline(in,line)){std::istringstream f(line);std::string kind;f>>kind;if(kind!="structure")continue;unsigned k=0,n=0;int rail=0,support=0,smooth=0,follow=0;world_structure::Definition d;f>>d.id>>k>>std::quoted(d.alias)>>d.spacing>>d.width>>d.height>>d.thickness>>d.rail_height>>d.support_depth>>rail>>support>>smooth>>follow>>n;d.kind=world_structure::Kind(k);d.railings=rail;d.supports=support;d.smooth=smooth;d.follow_ground=follow;for(unsigned i=0;i<n;++i){world_structure::Point p;f>>p.x>>p.y>>p.z;d.points.push_back(p);}if(d.id==5)bridge=d;}assert(bridge.id==5);
 world_structure_runtime::Prepared geometry;std::string error;assert(world_structure_runtime::prepare({bridge},[](double x,double z,const void*){return double(world_atlas_height(x,z));},nullptr,geometry,error));assert(geometry.meshes.size()==1);const auto&m=geometry.meshes[0];world_playtest_walk::Support collision;world_playtest_walk::Bounds b{m.bounds[0]-.1,m.bounds[1]+.1,m.bounds[4]-.1,m.bounds[5]+.1,m.bounds[2]-1,m.bounds[3]+3};world_playtest_walk::Spawn spawn{-12018,12.075,5164};assert(collision.configure(m.collision,b,spawn,error,false));unsigned samples=0,wet_covered=0;
 for(unsigned direction=0;direction<2;++direction){float feet=12.0f;double px=0,pz=0;for(unsigned k=0;k<=180;++k){double t=.03+.94*k/180.;if(direction)t=1-t;double x=-12028+20*t,z=5160+8*t;float floor=0;double expected=12.0+.15*t;assert(collision.sample(x,z,expected,floor));assert(std::abs(floor-expected)<.003);assert(collision.standing_clear(x,z,floor));if(k){float next=0;if(!collision.can_move(px,pz,x,z,feet,next)){std::cerr<<"move failed "<<x<<' '<<z<<' '<<feet<<'\n';return 3;}assert(std::abs(next-floor)<.003);}feet=floor;px=x;pz=z;++samples;float level=0,depth=0;if(world_atlas_local_water(x,z,&level,&depth)){assert(feet>level+.4);++wet_covered;}}}
 assert(wet_covered>30);std::cout<<"Battlefield bridge passed "<<samples<<" bidirectional exact-Jolt walking/standing samples; "<<wet_covered<<" water-covered samples remain above water. Triangles="<<geometry.triangles<<" supports="<<m.supports<<" posts="<<m.posts<<'\n';world_atlas_shutdown();}
